mod tests {
    use super::*;
    use crate::test_util::{has_id, lint_nodes, parse};
    use mlt_core::Config;

    #[test]
    fn skip_checks_disables_check() {
        let config = Config::from_toml(
            "[lint.rules.DEPLOYMENT_ENGINE]\nskip_checks = [\"MCTBX\"]\n",
        )
        .expect("valid config");
        let rule = DeploymentEngine::from_config(&config);
